import os, re
from datetime import date, timedelta

ref = date(2025, 8, 12)
ranges = {
    'today': (ref, ref),
    'last_7_days': (ref - timedelta(days=6), ref),
    'last_30_days': (ref - timedelta(days=29), ref),
    'month_to_date': (date(ref.year, ref.month, 1), ref),
}
sevs = ['ERROR', 'WARNING', 'INFO']
counts = {p: {s: 0 for s in sevs} for p in ranges}
total = {s: 0 for s in sevs}

for fn in os.listdir('/app/logs'):
    m = re.match(r'(\d{4})-(\d{2})-(\d{2})_', fn)
    if not m:
        continue
    d = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    with open(os.path.join('/app/logs', fn)) as f:
        for line in f:
            for s in sevs:
                if ('[%s]' % s) in line:
                    total[s] += 1
                    for p, (lo, hi) in ranges.items():
                        if lo <= d <= hi:
                            counts[p][s] += 1

order = ['today', 'last_7_days', 'last_30_days', 'month_to_date']
with open('/app/summary.csv', 'w') as out:
    out.write('period,severity,count\n')
    for p in order:
        for s in sevs:
            out.write('%s,%s,%d\n' % (p, s, counts[p][s]))
    for s in sevs:
        out.write('total,%s,%d\n' % (s, total[s]))
EOF
